import json,numpy as np
p=np.load('p_joint.npy')
XL,mq,kiv,kpv,mp,TVf,TQf,TPf=[float(x) for x in p]
sub={
 "params":{"XL":XL,"mq":mq,"kiv":kiv,"kpv":kpv,"mp":mp,"TVf":TVf,"TQf":TQf,"TPf":TPf,"w0":2*np.pi*60,"Emax":1.15},
 "defs":{
   "a":"P0*XL/V0",
   "b":"V0+Q0*XL/V0",
   "Vcmd":"Vset+mq*(Q0-Qm)",
   "Eraw":"xv+kpv*(Vcmd-Vm)",
   "E":"Min(Max(Eraw,0),Emax)",
   "c":"delta-theta",
   "Pi":"V*E*sin(c)/XL",
   "Qi":"V*(E*cos(c)-V)/XL"
 },
 "states":{
   "Pm":{"rhs":"(Pi-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Qi-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"sqrt(a**2+b**2)"},
   "delta":{"rhs":"w0*mp*(P0-Pm)","init":"theta0+atan2(a,b)"}
 },
 "outputs":{"P":"Pi","Q":"Qi"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(sub['params'])

